package vn.edu.t3h.repository.impl;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import vn.edu.t3h.model.User;
import vn.edu.t3h.repository.UserRepository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

public class UserRepositoryImpl implements UserRepository {

    private JdbcTemplate jdbcTemplate;

    public void setJdbcTemplate(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    private final RowMapper<User> rowMapper = new RowMapper<User>() {
        @Override
        public User mapRow(ResultSet rs, int rowNum) throws SQLException {
            User u = new User();
            u.setId(rs.getInt("id"));
            u.setFullName(rs.getString("full_name"));
            u.setEmail(rs.getString("email"));
            u.setPasswordHash(rs.getString("password_hash"));

            java.sql.Date bd = rs.getDate("birthday");
            if (bd != null) u.setBirthday(bd.toLocalDate());

            u.setGender(rs.getString("gender"));
            try { u.setRole(rs.getString("role")); } catch (SQLException ignore) {}
            try { u.setRememberToken(rs.getString("remember_token")); } catch (SQLException ignore) {}
            try { u.setAvatar(rs.getString("avatar")); } catch (SQLException ignore) {}

            Timestamp created = rs.getTimestamp("created_at");
            if (created != null) u.setCreatedAt(created.toLocalDateTime());
            Timestamp updated = rs.getTimestamp("updated_at");
            if (updated != null) u.setUpdatedAt(updated.toLocalDateTime());

            return u;
        }
    };

    @Override
    public List<User> findAll(String keyword, String role) {
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, full_name, email, password_hash, birthday, gender, role, remember_token, avatar, created_at, updated_at ")
           .append("FROM users WHERE 1=1 ");

        List<Object> args = new ArrayList<>();

        if (keyword != null && !keyword.isBlank()) {
            sql.append(" AND (full_name LIKE ? OR email LIKE ?) ");
            String kw = "%" + keyword.trim() + "%";
            args.add(kw);
            args.add(kw);
        }

        if (role != null && !role.isBlank() && !"ALL".equalsIgnoreCase(role)) {
            sql.append(" AND role = ? ");
            args.add(role.trim());
        }

        sql.append(" ORDER BY id DESC");
        return jdbcTemplate.query(sql.toString(), rowMapper, args.toArray());
    }

    @Override
    public User findById(Integer id) {
        String sql = "SELECT id, full_name, email, password_hash, birthday, gender, role, remember_token, avatar, created_at, updated_at FROM users WHERE id = ?";
        List<User> list = jdbcTemplate.query(sql, rowMapper, id);
        return list.isEmpty() ? null : list.get(0);
    }

    @Override
    public User findByEmail(String email) {
        String sql = "SELECT id, full_name, email, password_hash, birthday, gender, role, remember_token, avatar, created_at, updated_at FROM users WHERE email = ?";
        List<User> list = jdbcTemplate.query(sql, rowMapper, email);
        return list.isEmpty() ? null : list.get(0);
    }

    @Override
    public int insert(User user) {
        String sql = "INSERT INTO users (full_name, email, password_hash, birthday, gender, role, avatar) VALUES (?, ?, ?, ?, ?, ?, ?)";
        return jdbcTemplate.update(
                sql,
                user.getFullName(),
                user.getEmail(),
                user.getPasswordHash(),
                user.getBirthday() == null ? null : java.sql.Date.valueOf(user.getBirthday()),
                user.getGender(),
                user.getRole() == null || user.getRole().isBlank() ? "USER" : user.getRole(),
                user.getAvatar()
        );
    }

    @Override
    public int update(User user) {
        String sql = "UPDATE users SET full_name = ?, email = ?, password_hash = ?, birthday = ?, gender = ?, role = ?, avatar = ? WHERE id = ?";
        return jdbcTemplate.update(
                sql,
                user.getFullName(),
                user.getEmail(),
                user.getPasswordHash(),
                user.getBirthday() == null ? null : java.sql.Date.valueOf(user.getBirthday()),
                user.getGender(),
                user.getRole(),
                user.getAvatar(),
                user.getId()
        );
    }

    @Override
    public int deleteById(Integer id) {
        String sql = "DELETE FROM users WHERE id = ?";
        return jdbcTemplate.update(sql, id);
    }
}

package vn.edu.t3h.service;

import vn.edu.t3h.dto.request.UserCreateRequest;
import vn.edu.t3h.dto.request.UserUpdateRequest;
import vn.edu.t3h.dto.response.UserListItemResponse;
import vn.edu.t3h.model.User;

import java.util.List;

public interface UserService {
    List<UserListItemResponse> getUsers(String keyword, String role);

    User getUserById(Integer id);

    void createUser(UserCreateRequest request);

    void updateUser(UserUpdateRequest request);

    void deleteUser(Integer id);
}

package vn.edu.t3h.service.impl;

import vn.edu.t3h.dto.request.UserCreateRequest;
import vn.edu.t3h.dto.request.UserUpdateRequest;
import vn.edu.t3h.dto.response.UserListItemResponse;
import vn.edu.t3h.exception.NotFoundException;
import vn.edu.t3h.exception.ValidationException;
import vn.edu.t3h.mapper.UserMapper;
import vn.edu.t3h.model.User;
import vn.edu.t3h.repository.UserRepository;
import vn.edu.t3h.service.UserService;
import vn.edu.t3h.util.PasswordUtil;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public class UserServiceImpl implements UserService {

    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");

    private UserRepository userRepository;

    public void setUserRepository(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @Override
    public List<UserListItemResponse> getUsers(String keyword, String role) {
        return userRepository.findAll(keyword, role)
                .stream()
                .map(UserMapper::toListItem)
                .collect(Collectors.toList());
    }

    @Override
    public User getUserById(Integer id) {
        User u = userRepository.findById(id);
        if (u == null) throw new NotFoundException("User not found: id=" + id);
        return u;
    }

    @Override
    public void createUser(UserCreateRequest request) {
        Map<String, String> errors = validateCreate(request);
        if (!errors.isEmpty()) {
            throw new ValidationException("Invalid create user", errors);
        }

        if (userRepository.findByEmail(request.getEmail().trim()) != null) {
            errors.put("email", "Email already exists");
            throw new ValidationException("Invalid create user", errors);
        }

        User user = UserMapper.fromCreateRequest(request);
        user.setPasswordHash(PasswordUtil.md5(request.getPassword()));
        if (user.getRole() == null || user.getRole().isBlank()) user.setRole("USER");

        userRepository.insert(user);
    }

    @Override
    public void updateUser(UserUpdateRequest request) {
        Map<String, String> errors = validateUpdate(request);
        if (!errors.isEmpty()) {
            throw new ValidationException("Invalid update user", errors);
        }

        User existing = userRepository.findById(request.getId());
        if (existing == null) {
            throw new NotFoundException("User not found: id=" + request.getId());
        }

        User byEmail = userRepository.findByEmail(request.getEmail().trim());
        if (byEmail != null && !byEmail.getId().equals(existing.getId())) {
            errors.put("email", "Email already exists");
            throw new ValidationException("Invalid update user", errors);
        }

        User update = UserMapper.fromUpdateRequest(request);

        if (request.getPassword() == null || request.getPassword().isBlank()) {
            update.setPasswordHash(existing.getPasswordHash());
        } else {
            update.setPasswordHash(PasswordUtil.md5(request.getPassword()));
        }

        if (update.getRole() == null || update.getRole().isBlank()) update.setRole(existing.getRole());

        userRepository.update(update);
    }

    @Override
    public void deleteUser(Integer id) {
        User existing = userRepository.findById(id);
        if (existing == null) throw new NotFoundException("User not found: id=" + id);
        userRepository.deleteById(id);
    }

    private Map<String, String> validateCreate(UserCreateRequest r) {
        Map<String, String> errors = new HashMap<>();
        if (r.getFullName() == null || r.getFullName().isBlank()) errors.put("fullName", "Full name is required");
        if (r.getEmail() == null || r.getEmail().isBlank()) {
            errors.put("email", "Email is required");
        } else if (!EMAIL.matcher(r.getEmail().trim()).matches()) {
            errors.put("email", "Email format is invalid");
        }
        if (r.getPassword() == null || r.getPassword().isBlank()) errors.put("password", "Password is required");
        return errors;
    }

    private Map<String, String> validateUpdate(UserUpdateRequest r) {
        Map<String, String> errors = new HashMap<>();
        if (r.getId() == null) errors.put("id", "Id is required");
        if (r.getFullName() == null || r.getFullName().isBlank()) errors.put("fullName", "Full name is required");
        if (r.getEmail() == null || r.getEmail().isBlank()) {
            errors.put("email", "Email is required");
        } else if (!EMAIL.matcher(r.getEmail().trim()).matches()) {
            errors.put("email", "Email format is invalid");
        }
        return errors;
    }
}

package vn.edu.t3h.util;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

public final class PasswordUtil {

    private PasswordUtil() {
    }

    public static String md5(String raw) {
        if (raw == null) return null;
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(raw.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            throw new IllegalStateException("Cannot hash password", e);
        }
    }
}

    .shadow-soft { box-shadow: 0 12px 30px rgba(17, 24, 39, 0.07); }

    .pill {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 6px 12px;
      border-radius: 999px;
      font-weight: 700;
      font-size: .85rem;
      border: 1px solid rgba(17, 24, 39, 0.08);
      background: rgba(255, 255, 255, 0.65);
    }

    .pill-admin {
      border-color: rgba(229, 0, 18, 0.25);
      background: rgba(229, 0, 18, 0.08);
      color: #b1000d;
    }

    .pill-user {
      border-color: rgba(17, 24, 39, 0.15);
      background: rgba(17, 24, 39, 0.04);
      color: #111827;
    }

    .searchbox {
      border-radius: 12px;
      border: 1px solid rgba(17, 24, 39, 0.10);
      padding: 10px 12px;
      background: rgba(255,255,255,.85);
    }

    .searchbox:focus {
      box-shadow: 0 0 0 .25rem var(--ring);
      border-color: rgba(229, 0, 18, 0.35);
    }

    .btn-brand {
      background: var(--brand);
      border-color: var(--brand);
      border-radius: 12px;
      font-weight: 800;
    }
<%@ page contentType="text/html; charset=UTF-8" pageEncoding="UTF-8" %>
    .btn-brand:hover { background: #c80010; border-color: #c80010; }
<%@ taglib prefix="c" uri="jakarta.tags.core" %>
    .table thead th {
      font-size: .8rem;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--muted);
      border-bottom: 1px solid rgba(17, 24, 39, 0.08);
      white-space: nowrap;
    }

    .table tbody td { vertical-align: middle; }
    .table tbody tr:hover { background: rgba(17, 24, 39, 0.02); }

    .avatar {
      width: 42px; height: 42px;
      border-radius: 14px;
      overflow: hidden;
      border: 1px solid rgba(17, 24, 39, 0.08);
      background: linear-gradient(135deg, rgba(229,0,18,.20), rgba(17,24,39,.06));
      display: inline-flex;
      align-items: center;
      justify-content: center;
      font-weight: 900;
      color: rgba(17, 24, 39, 0.8);
    }

    .avatar img { width: 100%; height: 100%; object-fit: cover; }

    .badge-gender {
      border-radius: 999px;
      font-weight: 800;
      font-size: .8rem;
      padding: 6px 10px;
      border: 1px solid rgba(17, 24, 39, 0.10);
      background: rgba(255,255,255,.7);
      color: #111827;
      white-space: nowrap;
    }

    .page-title { font-weight: 900; letter-spacing: -0.8px; }
    .subtle { color: var(--muted); }

    .action-btn { border-radius: 10px; }

    .empty { padding: 70px 20px; text-align: center; color: var(--muted); }
    .empty i { font-size: 56px; color: rgba(17, 24, 39, 0.20); }
  </style>
</head>

<body>

  <div class="topbar">
    <div class="container shell py-3 d-flex align-items-center justify-content-between">
      <div class="d-flex align-items-center gap-3">
        <div class="brand fs-4">Admin<span class="dot">.</span>Users</div>
        <span class="pill"><i class="bi bi-shield-check"></i> User Management</span>
      </div>

      <div class="d-flex align-items-center gap-2">
        <a class="btn btn-outline-dark action-btn" href="${pageContext.request.contextPath}/products" title="Home">
          <i class="bi bi-house"></i>
        </a>
        <a class="btn btn-brand text-white action-btn" href="${pageContext.request.contextPath}/admin/users/create">
          <i class="bi bi-plus-lg me-1"></i> Tạo user
        </a>
      </div>
    </div>
  </div>

  <div class="container shell my-4">

    <c:if test="${not empty successMessage}">
      <div class="alert alert-success card-elev shadow-soft border-0" role="alert">
        <i class="bi bi-check-circle me-2"></i><c:out value="${successMessage}" />
      </div>
    </c:if>

    <c:if test="${not empty errorMessage}">
      <div class="alert alert-danger card-elev shadow-soft border-0" role="alert">
        <i class="bi bi-exclamation-triangle me-2"></i><c:out value="${errorMessage}" />
      </div>
    </c:if>

    <div class="card-elev p-4 mb-4">
      <div class="d-flex flex-wrap align-items-end justify-content-between gap-3">
        <div>
          <div class="page-title h3 mb-1">Danh sách người dùng</div>
          <div class="subtle">Quản lý người dùng (search, filter, CRUD).</div>
        </div>

        <div class="d-flex align-items-center gap-2">
          <span class="pill"><i class="bi bi-people"></i>
            <c:out value="${users.size()}" /> users
          </span>
        </div>
      </div>

      <hr class="my-4" />

      <form class="row g-2 align-items-end" method="get" action="${pageContext.request.contextPath}/admin/users">
        <div class="col-12 col-lg-6">
          <label class="form-label fw-semibold">Tìm kiếm</label>
          <div class="input-group">
            <span class="input-group-text" style="border-radius: 12px 0 0 12px; border: 1px solid rgba(17,24,39,.10);">
              <i class="bi bi-search"></i>
            </span>
            <input class="form-control searchbox" name="keyword" value="<c:out value='${keyword}'/>" placeholder="Tìm theo họ tên hoặc email..." />
          </div>
        </div>

        <div class="col-12 col-md-6 col-lg-3">
          <label class="form-label fw-semibold">Role</label>
          <select class="form-select searchbox" name="role">
            <option value="ALL" <c:if test="${empty role || role == 'ALL'}">selected</c:if>>ALL</option>
            <option value="USER" <c:if test="${role == 'USER'}">selected</c:if>>USER</option>
            <option value="ADMIN" <c:if test="${role == 'ADMIN'}">selected</c:if>>ADMIN</option>
          </select>
        </div>

        <div class="col-12 col-md-6 col-lg-3 d-grid">
          <button class="btn btn-brand text-white" type="submit">
            <i class="bi bi-funnel me-1"></i> Áp dụng
          </button>
        </div>
      </form>
    </div>

    <div class="card-elev p-3 p-md-4">
      <div class="table-responsive">
        <table class="table align-middle mb-0">
          <thead>
          <tr>
            <th style="width: 70px;">Avatar</th>
            <th>Full name</th>
            <th>Email</th>
            <th>Gender</th>
            <th>Birthday</th>
            <th>Role</th>
            <th>Created</th>
            <th class="text-end">Actions</th>
          </tr>
          </thead>

          <tbody>
          <c:if test="${empty users}">
            <tr>
              <td colspan="8">
                <div class="empty">
                  <i class="bi bi-emoji-frown"></i>
                  <div class="mt-3 fw-bold">Không có user nào</div>
                  <div class="mt-1">Thử đổi bộ lọc hoặc tạo mới.</div>
                </div>
              </td>
            </tr>
          </c:if>

          <c:forEach items="${users}" var="u">
            <tr>
              <td>
                <div class="avatar">
                  <c:choose>
                    <c:when test="${not empty u.avatar}">
                      <img src="<c:out value='${u.avatar}'/>" alt="avatar" />
                    </c:when>
                    <c:otherwise>
                      <span>
                        <c:choose>
                          <c:when test="${not empty u.fullName}"><c:out value="${fn:substring(u.fullName,0,1)}" /></c:when>
                          <c:otherwise>U</c:otherwise>
                        </c:choose>
                      </span>
                    </c:otherwise>
                  </c:choose>
                </div>
              </td>
              <td class="fw-semibold"><c:out value="${u.fullName}" /></td>
              <td><c:out value="${u.email}" /></td>
              <td><span class="badge-gender"><c:out value="${empty u.gender ? '—' : u.gender}" /></span></td>
              <td><c:out value="${empty u.birthday ? '—' : u.birthday}" /></td>
              <td>
                <c:choose>
                  <c:when test="${u.role == 'ADMIN'}">
                    <span class="pill pill-admin"><i class="bi bi-shield-lock"></i> ADMIN</span>
                  </c:when>
                  <c:otherwise>
                    <span class="pill pill-user"><i class="bi bi-person"></i> USER</span>
                  </c:otherwise>
                </c:choose>
              </td>
              <td><c:out value="${empty u.createdAt ? '—' : u.createdAt}" /></td>
              <td class="text-end">
                <a class="btn btn-outline-dark btn-sm action-btn" href="${pageContext.request.contextPath}/admin/users/${u.id}/edit">
                  <i class="bi bi-pencil-square"></i>
                </a>

                <button class="btn btn-outline-danger btn-sm action-btn" type="button"
                        data-bs-toggle="modal" data-bs-target="#confirmDeleteModal"
                        data-user-id="${u.id}" data-user-name="<c:out value='${u.fullName}'/>">
                  <i class="bi bi-trash"></i>
                </button>
              </td>
            </tr>
          </c:forEach>
          </tbody>
        </table>
      </div>
    </div>

    <div class="modal fade" id="confirmDeleteModal" tabindex="-1" aria-hidden="true">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content" style="border-radius: 18px;">
          <div class="modal-header">
            <h5 class="modal-title fw-bold">Xác nhận xoá user</h5>
            <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div class="modal-body">
            Bạn chắc chắn muốn xoá <span class="fw-bold" id="deleteUserName">user</span>?
          </div>
          <div class="modal-footer">
            <button type="button" class="btn btn-outline-dark action-btn" data-bs-dismiss="modal">Huỷ</button>
            <form id="deleteForm" method="post" action="#" class="m-0">
              <button type="submit" class="btn btn-danger action-btn">
                <i class="bi bi-trash me-1"></i> Xoá
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>

    <div class="mt-4 footer-note">
      <div class="d-flex justify-content-between flex-wrap gap-2">
        <span>UI based on provided template.</span>
        <span>Spring MVC + JSP + JdbcTemplate.</span>
      </div>
    </div>

  </div>

  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
  <script>
    const modal = document.getElementById('confirmDeleteModal');
    modal.addEventListener('show.bs.modal', (event) => {
      const btn = event.relatedTarget;
      const id = btn.getAttribute('data-user-id');
      const name = btn.getAttribute('data-user-name');

      document.getElementById('deleteUserName').textContent = name || 'user';
      document.getElementById('deleteForm').action = `${'${pageContext.request.contextPath}'}/admin/users/${id}/delete`;
    });
  </script>
</body>
</html>
<%@ taglib prefix="fn" uri="jakarta.tags.functions" %>
