    }

    .brand { font-weight: 900; letter-spacing: -0.6px; }
    .brand .dot { color: var(--brand); }
    .shell { max-width: 1200px; }

    .card-elev {
      background: var(--card);
      border: 1px solid rgba(17, 24, 39, 0.06);
      border-radius: 16px;
      box-shadow: 0 18px 45px rgba(17, 24, 39, 0.08);
    }
